int porch_light_log_header(char *buf, size_t size)
{
    return snprintf(buf, size, "motion,door,tod,open_long,plan");
}

int porch_light_log_row(const porch_light_state_t *s, char *buf, size_t size)
{
    const tlg_agent_t *a = &s->agent;
    int n = snprintf(buf, size, "%s,%s,%s,%s,", V_MOTION[s->in.motion], V_DOOR[s->in.door], V_TOD[s->in.tod], V_OPEN_LONG[s->in.open_long]);
    if (n < 0 || (size_t)n >= size) return n;
    if (!a->acted_ok || a->plan_len == 0)
        return n + snprintf(buf + n, size - (size_t)n, "%s", a->acted_ok ? "nothing" : "-");
    for (int i = 0; i < a->plan_len; i++) {
        int w = snprintf(buf + n, size - (size_t)n, "%s%s", i ? "+" : "", porch_light_domain.actions[a->plan[i]].name);
        if (w < 0 || (size_t)(n + w) >= size) return n + w;
        n += w;
    }
    return n;
}

int porch_light_status_json(const porch_light_state_t *s, char *buf, size_t size)
{
    const tlg_agent_t *a = &s->agent;
    int n = snprintf(buf, size, "{\"motion\":\"%s\",\"door\":\"%s\",\"tod\":\"%s\",\"open_long\":\"%s\",\"plan\":\"", V_MOTION[s->in.motion], V_DOOR[s->in.door], V_TOD[s->in.tod], V_OPEN_LONG[s->in.open_long]);
    if (n < 0 || (size_t)n >= size) return -1;
    if (!a->acted_ok || a->plan_len == 0)
        n += snprintf(buf + n, size - (size_t)n, "%s", a->acted_ok ? "nothing" : "-");
    for (int i = 0; a->acted_ok && i < a->plan_len && (size_t)n < size; i++)
        n += snprintf(buf + n, size - (size_t)n, "%s%s", i ? " " : "", porch_light_domain.actions[a->plan[i]].name);
    if ((size_t)n >= size) return -1;
    n += snprintf(buf + n, size - (size_t)n, "\"}");
    return (size_t)n < size ? n : -1;
}

